function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is an integer from 1 to nums.length.';
  return null;
}

