  let longest = 0;
  for (let start = 0; start < nums.length; start++) {
    const seen = {};
    for (let end = start; end < nums.length; end++) {
      seen[nums[end]] = (seen[nums[end]] || 0) + 1;
      if (seen[nums[end]] > k) break;
      longest = Math.max(longest, end - start + 1);
