function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(1500, 2000) : pick(1, 10);
  // A small pool of distinct values forces repeats; occasionally use huge values too.
  const poolSize = size === 'large' ? [2, 10, 100, 2000][pick(0, 3)] : pick(1, 4);
  const pool = Array.from({ length: poolSize }, () => (rand() < 0.3 ? pick(1, 1000000000) : pick(1, 50)));
  const nums = Array.from({ length: n }, () => pool[pick(0, poolSize - 1)]);
  const k = rand() < 0.7 ? pick(1, Math.min(n, size === 'large' ? 20 : 3)) : pick(1, n);
  return [nums, k];
}
